'use strict'

// Generated by vfs_scaffold_auth. Password hashing with scrypt (node:crypto, no dependency).
// Stored format, self-describing so the cost can be raised later without breaking old hashes:
//   scrypt$<N>$<r>$<p>$<salt, base64url>$<hash, base64url>

const crypto = require('node:crypto')

const PARAMS = { N: 32768, r: 8, p: 1 }
const KEY_LENGTH = 32
const SALT_BYTES = 16
const MAX_MEMORY = 128 * 1024 * 1024

// Bounds for parameters read back from the database, so a tampered row cannot make verification hang.
const LIMITS = { N: 1 << 20, r: 32, p: 16 }

function scrypt(password, salt, keyLength, params) {
  return new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, keyLength, { ...params, maxmem: MAX_MEMORY }, (error, key) => (error ? reject(error) : resolve(key)))
  })
}

const normalize = (password) => String(password).normalize('NFKC')

async function hashPassword(password) {
  const salt = crypto.randomBytes(SALT_BYTES)
  const hash = await scrypt(normalize(password), salt, KEY_LENGTH, PARAMS)
  return ['scrypt', PARAMS.N, PARAMS.r, PARAMS.p, salt.toString('base64url'), hash.toString('base64url')].join('$')
}

function parse(stored) {
  const parts = typeof stored === 'string' ? stored.split('$') : []
  if (parts.length !== 6 || parts[0] !== 'scrypt') return null
  const [N, r, p] = parts.slice(1, 4).map(Number)
  const powerOfTwo = Number.isInteger(N) && N > 1 && (N & (N - 1)) === 0
  if (!powerOfTwo || N > LIMITS.N || !Number.isInteger(r) || r < 1 || r > LIMITS.r || !Number.isInteger(p) || p < 1 || p > LIMITS.p) return null
  const salt = Buffer.from(parts[4], 'base64url')
  const hash = Buffer.from(parts[5], 'base64url')
  if (salt.length < 8 || hash.length < 16) return null
  return { N, r, p, salt, hash }
}

/** True when `password` matches the stored hash. Constant-time comparison. */
async function verifyPassword(password, stored) {
  const parsed = parse(stored)
  if (!parsed) return false
  const { N, r, p, salt, hash } = parsed
  const actual = await scrypt(normalize(password), salt, hash.length, { N, r, p })
  return crypto.timingSafeEqual(actual, hash)
}

/** True when the hash was made with weaker parameters than the current ones (rehash it after a successful login). */
function needsRehash(stored) {
  const parsed = parse(stored)
  return !parsed || parsed.N < PARAMS.N || parsed.r < PARAMS.r || parsed.p < PARAMS.p
}

// Spends the same time as a real check, for a login with an unknown email (no timing hint that the account is missing).
let dummyHash = null
async function verifyAgainstDummy(password) {
  if (!dummyHash) dummyHash = await hashPassword(crypto.randomBytes(16).toString('hex'))
  await verifyPassword(password, dummyHash)
  return false
}

module.exports = { hashPassword, verifyPassword, needsRehash, verifyAgainstDummy, PARAMS }
